## 4. Compliance Rule Engine

### 4.1 Rule Storage Format and Metadata

```csharp
// Compliance.Domain/RuleEngine/RuleDefinitions.cs
namespace Compliance.Domain.RuleEngine
{
    public class RuleDefinitionCatalog
    {
        // Percentage Limit Rules
        public static RuleDefinition IssuerExposureLimit => new()
        {
            Type = RuleType.PercentageLimit,
            Category = RuleCategory.Issuer,
            Name = "Max Issuer Exposure",
            Expression = @"
                var currentExposure = portfolio.GetIssuerExposure(security.IssuerId);
                var proposedExposure = currentExposure + trade.Amount;
                var limit = fund.NAV * (parameters.MaxPercentage / 100m);
                return proposedExposure <= limit;
            ",
            ParameterSchema = new Dictionary<string, Type>
            {
                { "MaxPercentage", typeof(decimal) }
            },
            CapacityCalculation = @"
                var currentExposure = portfolio.GetIssuerExposure(security.IssuerId);
                var limit = fund.NAV * (parameters.MaxPercentage / 100m);
                return Math.Max(0, limit - currentExposure);
            "
        };

        public static RuleDefinition SecurityTypeRestriction => new()
        {
            Type = RuleType.SecurityTypeRestriction,
            Category = RuleCategory.Security,
            Name = "Security Type Whitelist",
            Expression = @"
                var allowedTypes = parameters.AllowedTypes
                    .Split(',')
                    .Select(t => t.Trim())
                    .ToList();
                return allowedTypes.Contains(security.Type);
            ",
            ParameterSchema = new Dictionary<string, Type>
            {
                { "AllowedTypes", typeof(string) }  // CSV: "TBill,Corporate"
            },
            CapacityCalculation = @"
                var allowedTypes = parameters.AllowedTypes
                    .Split(',')
                    .Select(t => t.Trim())
                    .ToList();
                return allowedTypes.Contains(security.Type) 
                    ? decimal.MaxValue 
                    : 0m;
            "
        };

        public static RuleDefinition CreditRatingRequirement => new()
        {
            Type = RuleType.RatingRequirement,
            Category = RuleCategory.Rating,
            Name = "Minimum Credit Rating",
            Expression = @"
                var ratingOrder = new[] { ""AAA"", ""AA+"", ""AA"", ""AA-"", 
                    ""A+"", ""A"", ""A-"", ""BBB+"", ""BBB"", ""BBB-"", 
                    ""BB+"", ""BB"", ""BB-"", ""B+"", ""B"", ""B-"" };
                var minIndex = Array.IndexOf(ratingOrder, parameters.MinRating);
                var securityIndex = Array.IndexOf(ratingOrder, security.CreditRating);
                return securityIndex >= 0 && securityIndex <= minIndex;
            ",
            ParameterSchema = new Dictionary<string, Type>
            {
                { "MinRating", typeof(string) }
            },
            CapacityCalculation = @"
                var ratingOrder = new[] { ""AAA"", ""AA+"", ""AA"", ""AA-"", 
                    ""A+"", ""A"", ""A-"", ""BBB+"", ""BBB"", ""BBB-"", 
                    ""BB+"", ""BB"", ""BB-"", ""B+"", ""B"", ""B-"" };
                var minIndex = Array.IndexOf(ratingOrder, parameters.MinRating);
                var securityIndex = Array.IndexOf(ratingOrder, security.CreditRating);
                var meetsRating = securityIndex >= 0 && securityIndex <= minIndex;
                return meetsRating ? decimal.MaxValue : 0m;
            "
        };

        public static RuleDefinition ConcentrationLimit => new()
        {
            Type = RuleType.ConcentrationLimit,
            Category = RuleCategory.Security,
            Name = "Max Security Concentration",
            Expression = @"
                var currentPosition = portfolio.GetSecurityPosition(security.Id);
                var proposedPosition = currentPosition + trade.Amount;
                var limit = fund.NAV * (parameters.MaxPercentage / 100m);
                return proposedPosition <= limit;
            ",
            ParameterSchema = new Dictionary<string, Type>
            {
                { "MaxPercentage", typeof(decimal) }
            },
            CapacityCalculation = @"
                var currentPosition = portfolio.GetSecurityPosition(security.Id);
                var limit = fund.NAV * (parameters.MaxPercentage / 100m);
                return Math.Max(0, limit - currentPosition);
            "
        };
    }

    public class RuleDefinition
    {
        public RuleType Type { get; init; }
        public RuleCategory Category { get; init; }
        public string Name { get; init; }
        public string Expression { get; init; }
        public string CapacityCalculation { get; init; }
        public Dictionary<string, Type> ParameterSchema { get; init; }
    }
}
