using Compliance.API.Services;
using Compliance.Domain.RuleEngine;
using Compliance.Infrastructure.Repositories;
using Microsoft.AspNetCore.Diagnostics;
using Shared.Common.Middleware;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container
builder.Services.AddControllers();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(c =>
{
    c.SwaggerDoc("v1", new() {
        Title = "Compliance API",
        Version = "v1",
        Description = "Trade compliance evaluation and rule engine API"
    });
});

// Register services
builder.Services.AddScoped<IComplianceService, ComplianceService>();
builder.Services.AddSingleton<IScriptEngine, RoslynScriptEngine>();
builder.Services.AddScoped<IRuleEvaluator, RuleEvaluator>();

// Register repositories (using mock implementations for now)
builder.Services.AddSingleton<IFundRepository, MockFundRepository>();
builder.Services.AddSingleton<ISecurityRepository, MockSecurityRepository>();
builder.Services.AddSingleton<IComplianceRuleRepository, MockComplianceRuleRepository>();
builder.Services.AddSingleton<IPortfolioRepository, MockPortfolioRepository>();

// Add exception handling
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();
builder.Services.AddProblemDetails();

// Add CORS
builder.Services.AddCors(options =>
{
    options.AddDefaultPolicy(policy =>
    {
        policy.AllowAnyOrigin()
              .AllowAnyHeader()
              .AllowAnyMethod();
    });
});

var app = builder.Build();

// Configure the HTTP request pipeline
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseExceptionHandler();
app.UseCors();
app.UseAuthorization();
app.MapControllers();

Console.WriteLine("Compliance API starting on http://localhost:5001");
app.Run("http://localhost:5001");

