using Allocation.API.Services;
using Allocation.API.Strategies;
using Shared.Common.Middleware;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container
builder.Services.AddControllers();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(c =>
{
    c.SwaggerDoc("v1", new() {
        Title = "Allocation API",
        Version = "v1",
        Description = "Trade allocation strategies API (Pro-Rata, Targeted, Custom)"
    });
});

// Register allocation strategies
builder.Services.AddTransient<ProRataAllocationStrategy>();
builder.Services.AddTransient<TargetedAllocationStrategy>();
builder.Services.AddTransient<CustomAllocationStrategy>();
builder.Services.AddSingleton<IAllocationStrategyFactory, AllocationStrategyFactory>();
builder.Services.AddScoped<IAllocationService, AllocationService>();

// Add exception handling
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();
builder.Services.AddProblemDetails();

// Add CORS
builder.Services.AddCors(options =>
{
    options.AddDefaultPolicy(policy =>
    {
        policy.AllowAnyOrigin()
              .AllowAnyHeader()
              .AllowAnyMethod();
    });
});

var app = builder.Build();

// Configure the HTTP request pipeline
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseExceptionHandler();
app.UseCors();
app.UseAuthorization();
app.MapControllers();

Console.WriteLine("Allocation API starting on http://localhost:5002");
app.Run("http://localhost:5002");

