using Allocation.API.Services;
using Microsoft.AspNetCore.Mvc;
using Shared.Contracts.DTOs;

namespace Allocation.API.Controllers;

[ApiController]
[Route("api/[controller]")]
public class AllocationController : ControllerBase
{
    private readonly IAllocationService _allocationService;
    private readonly ILogger<AllocationController> _logger;

    public AllocationController(
        IAllocationService allocationService,
        ILogger<AllocationController> logger)
    {
        _allocationService = allocationService;
        _logger = logger;
    }

    [HttpPost("distribute")]
    [ProducesResponseType(typeof(AllocationResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400)]
    public async Task<ActionResult<AllocationResponse>> Distribute(
        [FromBody] AllocationRequest request)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        _logger.LogInformation(
            "Received allocation request for {RequestId} with methodology {Methodology}",
            request.RequestId,
            request.Methodology);

        var response = await _allocationService.AllocateAsync(request);

        return Ok(response);
    }

    [HttpGet("health")]
    public IActionResult Health()
    {
        return Ok(new { status = "healthy", service = "Allocation.API" });
    }
}

